contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // run takes an amount to forward to c.go; contract must have enough balance to send it
    function run(uint256 amount) public payable {
        require(address(this).balance >= amount, "insufficient test balance");

        // observe owner and balances before the call
        address ownerBefore = c.owner();
        uint256 cBalBefore = address(c).balance;
        uint256 thisBalBefore = address(this).balance;

        bool reverted;
        // make the state-changing call as a top-level statement
        try c.go{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // observe after-values
        address ownerAfter = c.owner();
        uint256 cBalAfter = address(c).balance;
        uint256 thisBalAfter = address(this).balance;

        // If the call reverted, no observable state on c should have changed (owner and balance unchanged).
        // If it did not revert, owner must remain the same and any decrease in c's balance must have resulted
        // in an equal increase in this contract's balance (no creation or disappearance of Ether beyond the transfer).
        assert(
            reverted
            ? (ownerAfter == ownerBefore && cBalAfter == cBalBefore)
            : (ownerAfter == ownerBefore &&
               // c's balance decreased by some delta (possibly zero) and this contract's balance increased by that same delta
               ( (cBalBefore >= cBalAfter) && (thisBalAfter == thisBalBefore + (cBalBefore - cBalAfter)) )
              )
        );
    }

    // accept ETH forwarded to this test contract (fallback for receiving transfers)
    receive() external payable {}
}

